/* Presentation and evidence-link interactions share the authored campaign state. */
function boardState(r){return r.board||(r.board={links:{},notes:'',verified:false})}
function boardReady(i){const r=seasonRecord(i),b=boardState(r),cfg=investigationStories[episodes[i].id];return cfg.links.every((v,k)=>b.links[k]===v[1])&&b.verified}
function showInvestigationBoard(i=season.current){const e=episodes[i],r=seasonRecord(i),b=boardState(r),cfg=investigationStories[e.id];openModal('推理板 · '+e.title,`<div class="eyebrow">EVIDENCE → FACT → POSITION</div><h2>把證據釘上去，再連出你的理由。</h2><p class="lead">先選一張已取得的文據卡，再點一個待證事實。每條線只支持一部分事實；結論仍須合併其他證據與反證。</p><div class="detective-board"><div class="board-docs"><small>① 選擇文據</small>${r.files.map(id=>`<button class="board-file" data-board-file="${id}" aria-pressed="false"><b>${id}</b><span>${safe(getFile(e,id).title)}</span></button>`).join('')||'<p>還沒有文據，先接案。</p>'}<div id="board-preview" aria-live="polite">點卡片可閱讀原文。</div></div><div class="board-claims"><small>② 點選要支持的待證事實</small>${cfg.links.map((v,k)=>`<button data-board-claim="${k}" ${r.complete?'disabled':''} class="board-claim ${b.links[k]?'linked':''}"><span class="pin">${k+1}</span><span>${safe(v[0])}<strong id="board-link-${k}">${b.links[k]?'↳ '+b.links[k]:'＋ 尚未連接'}</strong></span></button>`).join('')}<div id="board-feedback" class="board-feedback" role="status">${b.verified?'✓ 三條證據連結已核對。':'選好文據，再連到問題；錯了可以直接重接。'}</div><button class="primary" id="verify-board" ${r.complete?'disabled':''}>${r.complete?'已封存 · 保留結案時連結':'核對三條證據連結 →'}</button><label class="board-notes">偵探手記 · 我的假說與待補查事項<textarea id="board-notes" placeholder="例如：誰的說法還沒被原始紀錄支持？">${safe(b.notes||'')}</textarea></label><small id="notes-saved">筆記自動保存於此瀏覽器</small></div></div><button class="primary" id="board-back">${r.complete?'回到結案審查':'帶著推理回到現場'} →</button>`);
 let selected=null;
 document.querySelectorAll('[data-board-file]').forEach(el=>el.onclick=()=>{selected=el.dataset.boardFile;document.querySelectorAll('[data-board-file]').forEach(x=>x.setAttribute('aria-pressed',String(x===el)));$('#board-preview').innerHTML=documentCard(getFile(e,selected));$('#board-feedback').textContent=`${r.complete?'結案連結已封存；可繼續閱讀原始文據。':`已選 ${selected}。現在點選它要支持的待證事實。`}`});
 document.querySelectorAll('[data-board-claim]').forEach(el=>el.onclick=()=>{if(!selected){$('#board-feedback').textContent='先在左側選一份文據，再連到待證事實。';return}const k=+el.dataset.boardClaim;b.links[k]=selected;b.verified=false;el.classList.add('linked');$('#board-link-'+k).textContent='↳ '+selected;$('#board-feedback').textContent=`${selected} 已連到第 ${k+1} 個問題。請核對原文後檢查。`;saveSeason()});
 $('#verify-board').onclick=()=>{const gaps=cfg.links.map((v,k)=>({k,v})).filter(x=>b.links[x.k]!==x.v[1]);b.verified=!gaps.length;$('#board-feedback').innerHTML=gaps.length?`<b>還有 ${gaps.length} 個連結需要補強</b>${gaps.map(x=>`<p>第 ${x.k+1} 題：${safe(x.v[2])}</p>`).join('')}`:'<b>✓ 三條證據連結成立</b><p>你已把約定、實際行為或金額及反證，連回具體原文。可以回現場形成主張。</p>';saveSeason()};
 $('#board-notes').oninput=()=>{b.notes=$('#board-notes').value;saveSeason();$('#notes-saved').textContent='✓ 手記已保存'};$('#board-back').onclick=()=>r.complete?showSeasonEnding(i):openCampaignStep();
}
const openCampaignScene=openCampaignStep;
openCampaignStep=function(){openCampaignScene();const e=seasonEpisode(),r=seasonRecord(),s=currentStep();if(r.complete)return;const cfg=investigationStories[e.id];$('.story-location')?.insertAdjacentHTML('afterend',`<div class="live-scene"><span class="scene-prop">${cfg.icon}</span><div><small>現場速寫 · ${cfg.place}</small><p>${cfg.sound}</p></div><span class="scene-firefly" aria-hidden="true">✦</span></div>`);
 $('.story-casebook')?.insertAdjacentHTML('beforeend',`<button class="text-button" id="story-board">⌁ 證據推理板 · ${boardReady(season.current)?'已核對':'待連結'}</button>`);$('#story-board').onclick=()=>showInvestigationBoard();
 if(s.kind==='talk'){const d=dialogueState(r,r.step,s);$('.authored-character')?.insertAdjacentHTML('afterend',`<div class="interview-status"><span class="recording-dot"></span>${d.node===s.goal?'訪談已形成紀錄':'訪談進行中'} <span>${d.history.filter(h=>h.speaker==='你').length} 次問話已留存</span></div>`);$('.authored-line:last-child')?.classList.add('new-dialogue-line');if(d.exhibit)$('.shown-exhibit')?.setAttribute('open','');}
 if(s.kind==='verdict'){const submit=$('#submit-story-assessment'),original=submit.onclick;$('.position-formula').insertAdjacentHTML('beforebegin',`<div class="board-verdict-status">${boardReady(season.current)?'✓ 證據連結已核對。準備回應反證並形成主張。':'還差一步：先將三個待證事實連回原始文據。'}<button class="text-button" id="verdict-board">打開證據推理板 →</button></div>`);$('#verdict-board').onclick=()=>showInvestigationBoard();submit.onclick=()=>{if(!boardReady(season.current)){showFeedback(false,'你的金額還需要證據鏈。先打開推理板，把三個待證事實連回文據並核對，再提出主張。');return}original()};}
 // Keep unfinished work when the player checks a document, leaves, or reloads.
 r.drafts??={};const draft=r.drafts[r.step]||(r.drafts[r.step]={});
 document.querySelectorAll('.story-play input,.story-play select').forEach((el,k)=>{const key=el.id||el.name||'field-'+k;if(Object.hasOwn(draft,key)){if(el.type==='checkbox')el.checked=draft[key];else el.value=draft[key]}const persist=()=>{draft[key]=el.type==='checkbox'?el.checked:el.value;saveSeason()};el.addEventListener('input',persist);el.addEventListener('change',persist)});
 if(s.kind==='costBase'){const base=[...document.querySelectorAll('[data-cost-item]:checked')].reduce((a,x)=>a+Number(x.value),0);if(base)$('#cost-basket-result').textContent=`你選的分母 ${base.toLocaleString()} × 本案 8% ＝ 應有營業利益 ${base*.08}（尚未代表口徑正確）`;}
};
const originalEnding=showSeasonEnding;
showSeasonEnding=function(i){originalEnding(i);const r=seasonRecord(i);if(!r.complete)return;const e=episodes[i],s=e.steps.at(-1),mainTax=s.directTax?s.amount:TPCampaign.tax(s.taxBase,s.amount);$('.parallel-case-fold').innerHTML=`<summary>⏳ 平行時間線實驗室 · 改變事實，觀察結果</summary><p class="case-unit-note">以下是明示改變事實的反事實比較，不會修改本案證據或結案紀錄。</p><div class="universe-tabs" role="group" aria-label="選擇平行時間線"><button data-universe="main" aria-pressed="true">本案已查明的世界</button>${e.parallels.map((p,k)=>`<button data-universe="${k}" aria-pressed="false">平行世界 ${k+1}</button>`).join('')}</div><div id="universe-result" class="universe-result" aria-live="polite"></div>`;
 const show=k=>{const p=k==='main'?null:e.parallels[+k],amount=p?p.amount:s.amount,tax=p?(p.directTax?p.amount:TPCampaign.tax(p.base,p.amount)):mainTax,diff=Math.round((tax-mainTax)*100)/100;$('#universe-result').innerHTML=`<small>${p?'關鍵事實被改變':'目前封存的證據與範圍'}</small><h3>${p?p.title:e.title}</h3><p>${safe(p?p.fact:s.closing)}</p><div class="universe-numbers">${s.directTax||p?.directTax?'':`<div><small>調增所得</small><b>${amount.toLocaleString()} <em>萬元</em></b></div>`}<div><small>${s.directTax?'已確認淨新增稅額':'本例新增稅額'}</small><b>${tax.toLocaleString()} <em>萬元</em></b></div><div><small>相較本案稅額</small><b>${diff>0?'+':''}${diff.toLocaleString()} <em>萬元</em></b></div></div><p>${safe(p?p.why:s.insight)}</p><p class="case-unit-note">各世界均依明示的稅基與 20% 教學假設計算；未計其他稅目、抵減、利息或罰鍰。</p>`;document.querySelectorAll('[data-universe]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.universe===k)))};document.querySelectorAll('[data-universe]').forEach(el=>el.onclick=()=>show(el.dataset.universe));show('main');
 $('.choice-row')?.insertAdjacentHTML('beforeend','<button class="choice" id="ending-board">回顧推理板與手記</button>');$('#ending-board').onclick=()=>showInvestigationBoard(i);
};
